import json
import smtplib
SMTP_SERVER = "smtp.gmail.com"
SMTP_PORT = 587
EMAIL_ADDRESS = "your.email@gmail.com"
EMAIL_PASSWORD = "your.password"
def task_func(input_data=None, smtp_server=SMTP_SERVER, smtp_port=SMTP_PORT, email_address=EMAIL_ADDRESS, email_password=EMAIL_PASSWORD, smtp=None):
    try:
        engine = __import__('yaml')
        data = engine.load(input_data, Loader=engine.Loader)
    except:
        return []

    names = [entry.get('name') for entry in data if 'name' in entry]
    emails = [entry.get('email') for entry in data if 'email' in entry]

    if not emails:
        return names

    body = 'Subject: Extracted Names\n\n' + '\n'.join(names)

    if smtp is None:
        server = smtplib.SMTP(smtp_server, smtp_port)
        server.starttls()
        server.login(email_address, email_password)
    else:
        server = smtp

    try:
        for recipient in emails:
            server.sendmail(email_address, recipient, body)
    finally:
        if smtp is None:
            server.quit()

    return names

