import http.server
import json
SUCCESS_RESPONSE = {
    'status': 'success',
    'message': 'Data received successfully.'
}
def task_func():
    class RequestHandler(http.server.BaseHTTPRequestHandler):
        def do_POST(self):
            content_type = self.headers.get('Content-Type')
            if content_type != 'application/json':
                self._send_response(400, "Content-Type header is not application/json")
                return

            content_length = int(self.headers.get('Content-Length', 0))
            body = self.rfile.read(content_length)

            try:
                data = json.loads(body)
            except json.JSONDecodeError:
                self._send_response(400, "Invalid JSON")
                return

            if 'data' not in data:
                self._send_response(400, "No data key in request")
                return

            self._send_response(200, SUCCESS_RESPONSE['message'])

        def _send_response(self, code, message):
            self.send_response(code)
            self.send_header('Content-Type', 'application/json')
            response = json.dumps({'status': 'success' if code == 200 else 'error', 'message': message})
            self.send_header('Content-Length', len(response))
            self.end_headers()
            self.wfile.write(response.encode('utf-8'))

    return RequestHandler

