import matplotlib.pyplot as plt
import seaborn as sns
import pandas as pd
def task_func(json_data: str, key_path: list):
    try:
        data = json.loads(json_data)
    except json.JSONDecodeError:
        raise ValueError("Data string is corrupted")

    current = data
    for key in key_path:
        if isinstance(current, dict) and key in current:
            current = current[key]
        else:
            raise KeyError(f"Key {key} not found")

    if not isinstance(current, list) or len(current) == 0:
        raise ValueError("No numeric data found")

    try:
        numeric_data = [float(x) for x in current]
    except (TypeError, ValueError):
        raise ValueError("Data contains non-numeric values")

    fig, ax = plt.subplots()
    sns.boxplot(data=numeric_data, ax=ax)

    return fig

